#!/bin/sh
# Import BOTH d5-candidate jobs (v3) - pick A or B on the cutter panel.
SERVER="${1:-http://localhost:8080}"
curl -sS -X POST "$SERVER/jobs/import-json" -H 'Content-Type: application/json' -d '{"name": "roll-v3-A", "barcode_link_info": "A0200ROLL", "command_type": 0, "regmark_fx": 60, "regmark_fy": 400, "regmark_rx": 0, "regmark_ry": 0, "command_sequence": "", "command_sequence_encoding": "base64", "append_etx": false}'
echo
curl -sS -X POST "$SERVER/jobs/import-json" -H 'Content-Type: application/json' -d '{"name": "roll-v3-B", "barcode_link_info": "A0200ROLL", "command_type": 0, "regmark_fx": 60, "regmark_fy": -100, "regmark_rx": 0, "regmark_ry": 0, "command_sequence": "", "command_sequence_encoding": "base64", "append_etx": false}'
echo
